-- Partner performance analysis
--
-- Run after `dbt build`. The default DuckDB schemas are `main_analytics` and
-- `main_marts`. Every query is deliberately written against governed dbt
-- models rather than raw CSV files.

-- 1. Executive KPI cards
select *
from main_analytics.partner_kpi_summary;


-- 2. Revenue concentration: share generated by the top 10% of partners
with ranked_partners as (
    select
        seller_id,
        item_revenue,
        row_number() over (order by item_revenue desc) as revenue_rank,
        count(*) over () as partner_count,
        sum(item_revenue) over () as portfolio_revenue
    from main_analytics.partner_scorecard
)
select
    round(
        100.0 * sum(
            case
                when revenue_rank <= ceil(partner_count * 0.10) then item_revenue
                else 0
            end
        ) / max(portfolio_revenue),
        2
    ) as top_10_percent_partner_revenue_share
from ranked_partners;


-- 3. Customer experience for late versus on-time deliveries
select
    case
        when is_late = 1 then 'Late'
        when is_late = 0 then 'On time'
        else 'Unknown'
    end as delivery_status,
    count(*) as partner_orders,
    round(avg(review_score), 2) as average_review_score,
    round(100.0 * avg(is_low_review), 2) as low_review_percentage
from main_analytics.partner_order_performance
where is_delivered = 1
group by delivery_status
order by delivery_status;


-- 4. Portfolio distribution by action-oriented segment
select
    partner_segment,
    count(*) as partners,
    round(sum(item_revenue), 2) as item_revenue,
    round(100.0 * sum(item_revenue) / sum(sum(item_revenue)) over (), 2) as revenue_share_percentage,
    round(avg(late_delivery_rate) * 100, 2) as average_late_delivery_percentage,
    round(avg(average_review_score), 2) as average_review_score
from main_analytics.partner_scorecard
group by partner_segment
order by item_revenue desc;


-- 5. Monthly portfolio trend for an executive dashboard
select
    order_month,
    sum(order_count) as partner_orders,
    round(sum(item_revenue), 2) as item_revenue,
    round(sum(cancelled_orders) / nullif(sum(order_count), 0)::double * 100, 2)
        as cancellation_percentage,
    round(sum(late_orders) / nullif(sum(delivered_orders), 0)::double * 100, 2)
        as late_delivery_percentage,
    round(
        sum(average_review_score * reviewed_orders)
            / nullif(sum(reviewed_orders), 0),
        2
    ) as weighted_average_review_score
from main_analytics.partner_monthly_performance
group by order_month
order by order_month;
